<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,post} from '../api'
const supported=ref(false),items=ref<{name:string;size:number;createdAt:string;sha256:string}[]>([]),busy=ref(false),error=ref(''),message=ref('')
const cloud=ref(false)
async function load(){try{const [result,config]=await Promise.all([api<{supported:boolean;items:typeof items.value}>('/admin/backups'),api<{runtimeMode:string}>('/auth/config')]);supported.value=result.supported;items.value=result.items;cloud.value=config.runtimeMode==='cloud'}catch(e){error.value=(e as Error).message}}
async function create(){busy.value=true;error.value='';message.value='';try{await post('/admin/backups');message.value='备份已创建，校验文件已生成';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function verify(name:string){busy.value=true;error.value='';try{const result=await api<{valid:boolean}>(`/admin/backups/${name}/verify`);message.value=result.valid?'备份文件校验通过':'校验失败，请勿用于恢复'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="panel feature-panel"><div class="section-caption">运行与数据库备份<button v-if="supported" class="btn primary" :disabled="busy" @click="create">立即创建备份</button><a v-else-if="cloud" class="btn" href="https://console.neon.tech" target="_blank" rel="noopener noreferrer">打开云数据库控制台</a></div><p class="form-intro">{{cloud?'网站已切换到云端运行，业务数据保存在独立云数据库中。云端重启可能要求重新登录，但不会因此清空业务数据。':'本机模式使用构建后的页面，由后端直接提供访问；后台守护进程会在异常退出后重新启动。数据库每天凌晨 03:00 自动备份，启动时也会补充过期备份。'}}</p><p v-if="!supported" class="form-hint">{{cloud?'云数据库的恢复窗口与导出需在数据库控制台管理，请确认当前免费计划的恢复范围并另存重要数据。':'内置备份适用于本机文件数据库；其他数据库需要单独配置备份。'}}</p><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="message" class="inline-success" role="status">{{message}}</p><div v-if="supported" class="table-scroll"><table><thead><tr><th>备份文件</th><th>大小</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.name"><td><strong>{{item.name}}</strong><small>SHA-256：{{item.sha256.slice(0,16)}}…</small></td><td>{{(item.size/1024).toFixed(1)}} KB</td><td>{{new Date(item.createdAt).toLocaleString('zh-CN')}}</td><td><div class="toolbar-filters"><button class="text-button" :disabled="busy" @click="verify(item.name)">校验</button><a class="text-button" :href="'/api/admin/backups/'+item.name" download>下载备份</a><a class="text-button" :href="'/api/admin/backups/'+item.name+'/checksum'" download>下载校验文件</a></div></td></tr><tr v-if="!items.length"><td colspan="4" class="empty">暂无备份，可创建第一份备份。</td></tr></tbody></table></div><div v-if="supported" class="form-hint">恢复需停止服务后执行 restore.ps1，工具会先校验备份、验证数据库，并保留恢复前的副本。操作说明见项目中的 docs/operations.md；当前不提供在线覆盖恢复。</div></section></template>
